import {demoProfile,forecast,purchaseScenario,reducedCostProfile} from './demo-engine.js';
'use strict';
const byId=id=>document.getElementById(id);
const usd=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value).replace('-','−');
const profile=demoProfile(),asOf=profile.demoAsOf,baseForecast=forecast(profile,asOf);
const model={cash:profile.business.cashToday,obligations:baseForecast.breakdown.obligations,gap:baseForecast.breakdown.seasonalReserve,buffer:profile.business.minCashBuffer,van:15000,months:baseForecast.points.map(p=>p.label.split(' ')[0]),balances:baseForecast.points.map(p=>p.projectedCash)};
const available=baseForecast.availableToSpend,baselineLow=baseForecast.projectedLow.amount;
function evaluatePurchase(amount){const s=purchaseScenario(profile,asOf,amount,'2026-10-01');return {balances:s.after.points.map(p=>p.projectedCash),low:s.after.projectedLow.amount,shortfall:s.shortfall};}
const detailContent={
 cash:()=>['Cash Today',`<p>Example cash on <b>September 7, 2026</b>: <b>${usd(model.cash)}</b>.</p><p>No bank account is connected. Changes last until you reload.</p>`],
 spend:()=>['Available to Spend',`<div class="ledger"><div><span>Cash Today</span><strong>${usd(model.cash)}</strong></div><div><span>Upcoming obligations</span><strong>−${usd(model.obligations)}</strong></div><div><span>Seasonal shortfall reserve</span><strong>−${usd(model.gap)}</strong></div><div><span>Minimum buffer</span><strong>−${usd(model.buffer)}</strong></div><div><span>Snapshot estimate</span><strong>${usd(baseForecast.breakdown.snapshot)}</strong></div><div><span>Forecast headroom</span><strong>${usd(baseForecast.breakdown.forecastHeadroom)}</strong></div><div class="ledger-total"><span>Available to Spend</span><strong>${usd(available)}</strong></div></div><p>The spending cap is the lower of the snapshot estimate and forecast headroom, floored at zero. This example already falls <b>${usd(model.buffer-baselineLow)}</b> below the buffer, so Available to Spend is <b>${usd(available)}</b>. The same forecast engine and dated inputs are used in the V0 app.</p>`],
 low:()=>['Projected Low',`<p>The example reaches <b>${usd(baselineLow)}</b> in <b>March 2027</b>, putting it <b>${usd(model.buffer-baselineLow)}</b> below the <b>${usd(model.buffer)}</b> minimum buffer.</p><p>Every month is calculated from starting cash, seasonal revenue, recurring costs, and dated commitments. Tap About these numbers for the full ledger.</p>`],
 period:()=>['Next Strong Period','<p><b>April 2027</b> is the first rising month after the low followed by a second rising month, forward of the <b>September 7, 2026</b> starting date.</p><p>This example timing is not a prediction for either founding market.</p>'],
 runway:()=>['Cash Runway','<p>The example balance stays above zero for the full <b>12-month</b> view, so Cash Runway is shown as <b>12+ months</b>.</p><p>No projection beyond this year is supplied. A purchase or change in assumptions can shorten that runway.</p>'],
 scenario:()=>{const amount=readAmount('purchase-amount'),result=evaluatePurchase(amount);return ['The purchase calculation',`<div class="ledger"><div><span>Projected Low · before</span><strong>${usd(baselineLow)}</strong></div><div><span>October purchase</span><strong>−${usd(amount)}</strong></div><div class="ledger-total"><span>Projected Low · after</span><strong>${usd(result.low)}</strong></div><div><span>Below minimum buffer</span><strong>${usd(result.shortfall)}</strong></div></div><p>A cash purchase in October subtracts its full price from October and each following month; September and Today remain unchanged. No financing, trade-in, or offset is assumed.</p>`];},
 assumptions:()=>['The example, in full',`<p>This is the same dated charter-business example used by the V0 app, as of <b>September 7, 2026</b>. All month-end balances and spending caps are calculated from its explicit inputs, not supplied headline anchors.</p><div class="table-wrap"><table><thead><tr><th>Month end</th><th>Baseline cash</th><th>After van</th></tr></thead><tbody>${model.months.map((month,i)=>`<tr><td>${month} <span class="figure">${i<4?2026:2027}</span></td><td>${usd(model.balances[i])}</td><td>${usd(evaluatePurchase(model.van).balances[i])}</td></tr>`).join('')}</tbody></table></div><p class="footnote">No bank account is connected. Changes last until you reload.</p>`]
};
function openDetails(key){const [title,content]=detailContent[key]();byId('detail-title').textContent=title;byId('detail-content').innerHTML=content;byId('details').showModal();}
document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>openDetails(button.dataset.detail)));
byId('close-details').addEventListener('click',()=>byId('details').close());
byId('details').addEventListener('click',event=>{if(event.target!==byId('details'))return;const bounds=event.target.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)event.target.close();});
function switchScreen(name){document.querySelectorAll('.screen').forEach(screen=>screen.hidden=screen.id!=='screen-'+name);document.querySelectorAll('.product-nav [data-screen]').forEach(button=>{if(button.dataset.screen===name)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});}
document.querySelectorAll('[data-screen]').forEach(button=>button.addEventListener('click',()=>switchScreen(button.dataset.screen)));
function readAmount(id){const input=byId(id);return Math.min(Number(input.max),Math.max(0,Number(input.value)||0));}
function chart(target,scenarioAmount=null){const base=[model.cash,...model.balances];const scenario=scenarioAmount===null?null:[model.cash,...evaluatePurchase(scenarioAmount).balances];const W=830,H=285,L=56,R=23,T=32,B=44;const lowest=Math.min(0,...(scenario||base));const highest=Math.ceil(Math.max(...base)/10000)*10000;const x=i=>L+i*(W-L-R)/12;const y=value=>T+(highest-value)/(highest-lowest)*(H-T-B);const path=values=>'M'+values.map((value,i)=>`${x(i).toFixed(1)},${y(value).toFixed(1)}`).join(' L');const unit=value=>Math.abs(value)>=1000?(value<0?'−':'')+'$'+Math.round(Math.abs(value)/1000)+'k':usd(value);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Full-year example forecast, September 2026 through August 2027. Today is at the start. Projected Low: $6,500 in March. Next Strong Period: April.${scenario?' After purchase low: '+usd(evaluatePurchase(scenarioAmount).low)+'.':''}">`;
for(let i=0;i<4;i++){const value=lowest+(highest-lowest)*i/3;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(value)}" y2="${y(value)}" stroke="#000000" stroke-dasharray="1 7"/><text x="0" y="${y(value)+4}">${unit(value)}</text>`;}
svg+=`<line x1="${L}" x2="${W-R}" y1="${y(model.buffer)}" y2="${y(model.buffer)}" stroke="#000000" stroke-dasharray="4 5"/><line x1="${L}" x2="${L}" y1="${T-4}" y2="${H-B}" stroke="#000000" stroke-dasharray="2 4"/><text x="${L}" y="16">Today</text><path class="data-line" d="${path(base)}" fill="none" stroke="#000000" stroke-width="2.5" stroke-linejoin="round"/>`;
if(scenario)svg+=`<path d="${path(scenario)}" fill="none" stroke="#000000" stroke-dasharray="7 5" stroke-width="2.5" stroke-linejoin="round"/>`;
base.forEach((value,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(value)}" r="${i===7||i===8?4:2.5}" fill="#000000"><title>${i?model.months[i-1]+' month end':'Today'}: ${usd(value)}</title></circle>`;if(i)svg+=`<text x="${x(i)}" y="${H-15}" text-anchor="middle">${model.months[i-1]}</text>`;});
if(!scenario)svg+=`<text x="${x(7)}" y="${y(baselineLow)-18}" text-anchor="middle">LW / $6,500</text><text x="${x(8)+8}" y="${y(model.balances[7])-19}">April / strong period</text>`;
svg+='</svg>';byId(target).innerHTML=svg;}
function updatePurchase(){const amount=readAmount('purchase-amount'),result=evaluatePurchase(amount);byId('purchase-answer').classList.toggle('warning',result.shortfall>0);byId('purchase-answer').innerHTML=`<span>Projected Low · March</span><strong>${usd(result.low)}</strong><span>${result.shortfall>0?usd(result.shortfall)+' below':usd(result.low-model.buffer)+' above'} the ${usd(model.buffer)} buffer.</span>`;chart('purchase-chart',amount);}
byId('purchase-amount').addEventListener('input',updatePurchase);byId('saving-amount').addEventListener('input',()=>{const next=forecast(reducedCostProfile(profile,'fuel',readAmount('saving-amount')),asOf);byId('saving-total').textContent=usd(next.projectedLow.amount);});
let vanApplied=false;
byId('van-toggle').addEventListener('click',()=>{vanApplied=!vanApplied;byId('van-toggle').setAttribute('aria-pressed',String(vanApplied));byId('van-toggle').innerHTML=vanApplied?'Show before purchase <span>↶</span>':'See the van’s impact <span>↗</span>';byId('van-low').textContent=usd(vanApplied?evaluatePurchase(model.van).low:baselineLow);byId('van-status').textContent=vanApplied?'After the October purchase · below your buffer':'Before the purchase';document.querySelector('.scenario-sheet').classList.toggle('applied',vanApplied);});
chart('main-chart');updatePurchase();
if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.reveal').forEach(section=>observer.observe(section));}

byId('screen-upcoming').querySelector('.ledger').innerHTML=profile.upcoming.map(item=>`<div><span>${item.label}<small style="display:block">${item.dueDate}</small></span><strong>${usd(item.amount)}</strong></div>`).join('');
byId('saving-amount').dispatchEvent(new Event('input'));
